const e=[{provider:`revyl`,package:`@agent-device/revyl`,label:`Revyl`},{provider:`testmu`,package:`@agent-device/testmu`,label:`TestMu AI`},{provider:`webos`,package:`@agent-device/webos`,label:`LG webOS`},{provider:`tizen`,package:`@agent-device/tizen`,label:`Samsung Tizen`}];function t(t){return e.find(e=>e.provider===t)}function n(){return`  Plugins, installed separately: ${e.map(e=>`${e.label} (connect ${e.provider}; ${e.package})`).join(`, `)}. Run agent-device plugins add <package>, then retry agent-device connect <provider> with your original arguments.`}export{n,t};